def sets():
    out = []
    for lo in (1, 26, 51, 76):
        qs = [(q, o, a, e + KEY, SRC.format(n)) for n in sorted(Q) if lo <= n <= lo + 24 for q, o, a, e in [Q[n]]]
        out.append({"name": f"Q{lo}–{lo + 24}", "questions": qs, "keep_order": True})
    return out


